-- Version 6: complete sourced Icon Moments trait aliases and remove unused per-card design.
-- Source IDs below repeat the unchanged version-5 import; aliases are stored by catalog migration.
CREATE TEMP TABLE lfv4_trait_alias_import(resource_id bigint PRIMARY KEY,native_player_id bigint,rating bigint,trait1 bigint,trait2 bigint) ON COMMIT DROP;
SELECT p.definition_id,t.trait_id,s.native_player_id,'5bf399731c5cf5beb1702e1ad55250e1464790f5c7355542e56371cf4985378a'
FROM lfv4_trait_alias_import s
JOIN ultimateteam.player_card_definitions p ON s.resource_id=ANY(p.replacement_resource_ids) AND p.rating=s.rating
JOIN ultimateteam.traits t ON ((CASE t.mask_word WHEN 1 THEN s.trait1 ELSE s.trait2 END) & t.bit_value)<>0
ORDER BY p.definition_id,t.trait_id
ON CONFLICT(definition_id,trait_id) DO NOTHING;
LOCK TABLE ultimateteam.player_card_definitions IN ACCESS EXCLUSIVE MODE;
DO $migration$ BEGIN
    IF EXISTS(SELECT 1 FROM ultimateteam.player_card_definitions WHERE design_override_id IS NOT NULL) THEN
        RAISE EXCEPTION 'Cannot remove populated player card design overrides';
    END IF;
END $migration$;
ALTER TABLE ultimateteam.player_card_definitions DROP COLUMN design_override_id;
